package org.systemmaster.continuity;
import java.nio.file.*;import java.util.*;import static org.systemmaster.continuity.ResumeAuthorities.*;
public final class ResumeCoordinator{private final ResumeStore store;private final RecoveryStandingAuthority recovery;private final PlanAuthority plans;private final FenceAuthority fences;private final CompatibilityAuthority compatibility;private final ReconciliationAuthority reconciliation;private final ResourceAdmissionAuthority admission;private final RuntimeIdentityAuthority runtime;private final AttemptClock clock;private final RecoveryTransitionAuthority transitions;private final VerificationAuthority verification;
 public ResumeCoordinator(Path root,RecoveryStandingAuthority recovery,PlanAuthority plans,FenceAuthority fences,CompatibilityAuthority compatibility,ReconciliationAuthority reconciliation,ResourceAdmissionAuthority admission,RuntimeIdentityAuthority runtime,AttemptClock clock,RecoveryTransitionAuthority transitions,VerificationAuthority verification){store=new ResumeStore(root);this.recovery=Objects.requireNonNull(recovery);this.plans=Objects.requireNonNull(plans);this.fences=Objects.requireNonNull(fences);this.compatibility=Objects.requireNonNull(compatibility);this.reconciliation=Objects.requireNonNull(reconciliation);this.admission=Objects.requireNonNull(admission);this.runtime=Objects.requireNonNull(runtime);this.clock=Objects.requireNonNull(clock);this.transitions=Objects.requireNonNull(transitions);this.verification=Objects.requireNonNull(verification);}
 public StartResult startResume(String recoveryId,String planId,String claimId,long fenceEpoch){RecoveryStanding rs=recovery.current(req(recoveryId));RecoveryPlan p=plans.currentPlan(rs.recoveryId());if(p==null||!p.recoveryPlanId().equals(req(planId))||!p.recoveryId().equals(rs.recoveryId())||!p.ready())return StartResult.blocked("PLAN_NOT_CURRENT_OR_READY");fences.assertClaim(rs.recoveryId(),req(claimId),fenceEpoch);if(!Set.of("CLAIMED","RESTORING","RECONCILING").contains(rs.state()))return StartResult.blocked("RECOVERY_STATE_NOT_RESUMABLE");String gate=gate(p,rs);if(gate!=null)return StartResult.blocked(gate);String startKey=ResumeStore.sha(rs.recoveryId()+"|"+p.planDigest()+"|"+rs.recoveryEpoch());String requestDigest=ResumeStore.sha(startKey+"|"+claimId+"|"+fenceEpoch);AttemptStart st=store.tx(s->{String prior=s.startKeys().get(startKey);if(prior!=null)return ResumeStore.Decision.read(new AttemptStart(s.attempts().get(prior),true));long no=s.maxAttempt().getOrDefault(rs.workUnitId(),0L)+1;String id="attempt-"+ResumeStore.sha(rs.workUnitId()+"|"+rs.recoveryId()+"|"+rs.recoveryEpoch()+"|"+no+"|"+p.planDigest()+"|"+fenceEpoch).substring(0,24);ExecutionAttemptRef x=new ExecutionAttemptRef(id,rs.workUnitId(),no,rs.recoveryId(),p.checkpointRef(),fenceEpoch,req(runtime.runtimeIdentity(p)),clock.now(),null,null);return ResumeStore.Decision.append(new AttemptStart(x,false),ResumeStore.attemptFrame(x,startKey,requestDigest));});transitions.resumeStarted(rs.recoveryId(),rs.version(),st.attempt.attemptId());return new StartResult(Status.STARTED,st.attempt,st.existing,null);}
 public RecordedDecision recordDecision(RecordedDecision d){Objects.requireNonNull(d);if(!ResumeStore.sha(d.result()).equals(d.resultDigest()))throw new ReplayConflictException("result digest mismatch");String k=ResumeStore.key(d.workUnitId(),d.decisionSeq());String dig=ResumeStore.sha(d.workUnitId()+"|"+d.decisionSeq()+"|"+d.decisionType()+"|"+d.inputDigest()+"|"+d.resultDigest()+"|"+String.join(",",d.evidenceRefs()));return store.tx(s->{RecordedDecision prior=s.decisions().get(k);if(prior!=null){if(!prior.equals(d))throw new ReplayConflictException("decision identity conflict");return ResumeStore.Decision.read(prior);}return ResumeStore.Decision.append(d,ResumeStore.decisionFrame(d,dig));});}
 public String replayDecision(String workUnitId,long decisionSeq,String expectedInputDigest){RecordedDecision d=store.snapshot().decisions().get(ResumeStore.key(req(workUnitId),decisionSeq));if(d==null)throw new ReplayBlockedException("recorded decision missing");if(!d.inputDigest().equals(req(expectedInputDigest)))throw new ReplayBlockedException("recorded decision input mismatch");if(!ResumeStore.sha(d.result()).equals(d.resultDigest()))throw new ReplayBlockedException("recorded decision corrupt");return d.result();}
 public OutcomeResult recordResumeOutcome(String attemptId,long fenceEpoch,String outcome,List<String>verificationEvidence,long outcomeSeq){if(outcomeSeq<1)throw new IllegalArgumentException("outcomeSeq");String id=req(attemptId),o=req(outcome);ExecutionAttemptRef a=store.snapshot().attempts().get(id);if(a==null)throw new ResumeConflictException("unknown attempt");if(a.fenceEpoch()!=fenceEpoch)throw new ResumeConflictException("attempt fence mismatch");fences.assertFence(a.recoveryId(),fenceEpoch);List<String>ev=List.copyOf(verificationEvidence==null?List.of():verificationEvidence);String ed=ResumeStore.sha(String.join("|",ev));String requestDigest=ResumeStore.sha(id+"|"+outcomeSeq+"|"+o+"|"+ed);ResumeStore.Outcome stored=store.tx(s->{String key="O:"+id+":"+outcomeSeq;ResumeStore.Receipt prior=s.receipts().get(key);if(prior!=null){if(!prior.digest().equals(requestDigest))throw new ResumeConflictException("outcome identity conflict");return ResumeStore.Decision.read(s.outcomes().get(id+":"+outcomeSeq));}ResumeStore.Outcome x=new ResumeStore.Outcome(id,outcomeSeq,o,ed,clock.now());return ResumeStore.Decision.append(x,ResumeStore.outcomeFrame(x,requestDigest));});if("FAILED".equals(o)){transitions.recoveryFailed(a.recoveryId(),id,stored.evidenceDigest());return new OutcomeResult("RECOVERY_FAILED",false);}transitions.verificationPending(a.recoveryId(),id);Decision vd=verification.verify(a.recoveryId(),id,ev);if(vd==Decision.ALLOW&&!verification.unresolvedCriticalEffects(a.recoveryId())){transitions.markRecovered(a.recoveryId(),id,ev);return new OutcomeResult("RECOVERED",true);}return new OutcomeResult("VERIFICATION_PENDING",false);}
 public Optional<ExecutionAttemptRef> getAttempt(String id){return Optional.ofNullable(store.snapshot().attempts().get(id));} public Optional<RecordedDecision> getRecordedDecision(String w,long seq){return Optional.ofNullable(store.snapshot().decisions().get(ResumeStore.key(w,seq)));}
 private String gate(RecoveryPlan p,RecoveryStanding rs){Decision c=compatibility.allowed(p);if(c!=Decision.ALLOW)return c==Decision.DENY?"COMPATIBILITY_DENIED":"COMPATIBILITY_UNKNOWN";Decision r=reconciliation.complete(p);if(r!=Decision.ALLOW)return r==Decision.DENY?"RECONCILIATION_INCOMPLETE":"RECONCILIATION_UNKNOWN";Decision a=admission.admitted(rs.recoveryId(),p.resourceClass());if(a!=Decision.ALLOW)return a==Decision.DENY?"RESOURCE_DENIED":"RESOURCE_UNKNOWN";return null;}private static String req(String v){return RecordedDecision.req(v,"value");}private record AttemptStart(ExecutionAttemptRef attempt,boolean existing){}
 public record StartResult(Status status,ExecutionAttemptRef attempt,boolean idempotentExisting,String blocker){static StartResult blocked(String b){return new StartResult(Status.BLOCKED,null,false,b);}}public enum Status{STARTED,BLOCKED}public record OutcomeResult(String state,boolean recovered){} public static class ResumeConflictException extends RuntimeException{ResumeConflictException(String m){super(m);}}public static final class ReplayBlockedException extends ResumeConflictException{ReplayBlockedException(String m){super(m);}}public static final class ReplayConflictException extends ResumeConflictException{ReplayConflictException(String m){super(m);}}
}
